CREATE TABLE IF NOT EXISTS bak_20261019_ops_ai_tool_login_links AS
  SELECT 'cloud_ops_events' AS src, id AS row_id, length(meta) AS len_meta, NULL AS len_prompt, NULL AS len_response, NULL AS len_tool_calls, strftime('%Y-%m-%dT%H:%M:%SZ','now') AS scrubbed_at
