    FROM ops_ai_log WHERE (prompt LIKE '%magic-link%' OR prompt LIKE '%magic_link%' OR prompt LIKE '%magiclink%' OR prompt LIKE '%/login%token=%' OR prompt LIKE '%/login%code=%' OR prompt LIKE '%/auth/%token=%' OR prompt LIKE '%callback%token=%' OR prompt LIKE '%/verify%token=%' OR prompt LIKE '%signin%token=%' OR prompt LIKE '%sign-in code%' OR prompt LIKE '%login code%' OR prompt LIKE '%verification code%') OR (response LIKE '%magic-link%' OR response LIKE '%magic_link%' OR response LIKE '%magiclink%' OR response LIKE '%/login%token=%' OR response LIKE '%/login%code=%' OR response LIKE '%/auth/%token=%' OR response LIKE '%callback%token=%' OR response LIKE '%/verify%token=%' OR response LIKE '%signin%token=%' OR response LIKE '%sign-in code%' OR response LIKE '%login code%' OR response LIKE '%verification code%') OR (tool_calls LIKE '%magic-link%' OR tool_calls LIKE '%magic_link%' OR tool_calls LIKE '%magiclink%' OR tool_calls LIKE '%/login%token=%' OR tool_calls LIKE '%/login%code=%' OR tool_calls LIKE '%/auth/%token=%' OR tool_calls LIKE '%callback%token=%' OR tool_calls LIKE '%/verify%token=%' OR tool_calls LIKE '%signin%token=%' OR tool_calls LIKE '%sign-in code%' OR tool_calls LIKE '%login code%' OR tool_calls LIKE '%verification code%');

